static void build_l4proto_sctp(const struct nf_conntrack *ct, struct nethdr *n)
 {
 	ct_build_group(ct, ATTR_GRP_ORIG_PORT, n, NTA_PORT,
	      sizeof(struct nfct_attr_grp_port));
 	ct_build_u8(ct, ATTR_DCCP_STATE, n, NTA_DCCP_STATE);
 	ct_build_u8(ct, ATTR_DCCP_ROLE, n, NTA_DCCP_ROLE);
 }


 static void build_l4proto_tcp(const struct nf_conntrack *ct, struct nethdr *n)
 {
 	ct_build_group(ct, ATTR_GRP_ORIG_PORT, n, NTA_PORT,
	      sizeof(struct nfct_attr_grp_port));
 	ct_build_u8(ct, ATTR_TCP_STATE, n, NTA_TCP_STATE);
 }


 static void build_l4proto_udp(const struct nf_conntrack *ct, struct nethdr *n)
 {
 	ct_build_group(ct, ATTR_GRP_ORIG_PORT, n, NTA_PORT,
	      sizeof(struct nfct_attr_grp_port));
 }


 static void build_l4proto(const struct nf_conntrack *ct, struct nethdr *n)
 {
 	switch (ct->l4proto) {
 	case IPPROTO_DCCP:
 	build_l4proto_dccp(ct, n);
 	break;
 	case IPPROTO_SCTP:
 	build_l4proto_sctp(ct, n);
 	break;
 	case IPPROTO_TCP:
 	build_l4proto_tcp(ct, n);
 	break;
 	case IPPROTO_UDP:
 	build_l4proto_udp(ct, n);
 	break;
 	default:
 	break;
 	}
 }


 static void build_nethdr(const struct nf_conntrack *ct, struct nethdr *n)
 {
 	n->family = ct->family;
 	n->l3proto = ct->l3proto;
 	n->l4proto = ct->l4proto;
 	n->timeout = ct->timeout;
 	build_l4proto(ct, n);
 }


 static int nfct_snprintf(char *buf, size_t size, const struct nf_conntrack *ct)
 {
 	struct nethdr n;
 	size_t len;

 	build_nethdr(ct, &n);
 	len = sizeof(n);
 	if (len > size)
 	return -1;

 	memcpy(buf, &n, len);
 	return len;
 }


 int nfct_snprintf(char *buf, size_t size, const struct nf_conntrack *ct)
 {
 	return nfct_snprintf(buf, size, ct);
 }


